import { createHash, randomUUID } from "node:crypto";
import type { BusinessSession, BusinessSessionRunner } from "../ports/persistence.ts";
import type { AuthorityArtifactReference, CommandEnvelope, CommandResult, GstGstr3bArtifactBindingPayload, GstGstr3bArtifactExportPayload, GstGstr3bArtifactValidatePayload, GstGstr3bFactDecisionPayload, GstGstr3bFactPayload, GstGstr3bSchemaPackDecisionPayload, GstGstr3bSchemaPackRegisterPayload, GstGstr3bLaneSpec, GstGstr3bFactType } from "../commands.ts";
import { canonicalJson, computeCommandHash, computeResultHash } from "../commands.ts";
import { DomainError, IdempotencyConflictError, IdempotencyCorruptError } from "../../core/types.ts";
import { validateCommandEnvelope } from "./bookset-command-service.ts";
import { evaluateMapping, hashCanonical, MAX_ARTIFACT_JSON, type Diagnostic, type JsonObject, type Mapping, type Schema, validateMapping, validateSchema, validateValue } from "./return-artifact-engine.ts";

const REGISTER = "gst.gstr3b-schema-pack.register";
const VERIFY = "gst.gstr3b-schema-pack.verify";
const REJECT = "gst.gstr3b-schema-pack.reject";
const FACT_PROPOSE = "gst.gstr3b-fact.propose";
const FACT_CONFIRM = "gst.gstr3b-fact.confirm";
const FACT_REJECT = "gst.gstr3b-fact.reject";
const PREPARE = "gst.gstr3b.prepare";
const VALIDATE = "gst.gstr3b.validate";
const EXPORT = "gst.gstr3b.export";
const HASH = /^[0-9a-f]{64}$/;
const FACT_TYPES: readonly GstGstr3bFactType[] = ["PORTAL_GSTR1_LIABILITY", "PORTAL_GSTR2B_ITC", "REVERSE_CHARGE_INWARD", "IMPORT_GOODS_ITC", "IMPORT_SERVICES_ITC", "INELIGIBLE_ITC", "ITC_REVERSAL", "ITC_RECLAIM", "INTEREST_LATE_FEE", "CASH_LEDGER", "CREDIT_LEDGER", "TAX_DEPOSIT", "NIL_EXEMPT_NONGST", "INTERSTATE_UNREGISTERED_SUMMARY", "ECOMMERCE_9_5"];
const DEFAULT_LANES = ["OUTWARD_TAXABLE_SUPPLIES", "ZERO_RATED_NIL_EXEMPT_NON_GST", "INWARD_REVERSE_CHARGE", "INTERSTATE_UNREGISTERED_COMPOSITION_UIN", "ELIGIBLE_ITC", "ITC_REVERSALS_INELIGIBLE", "INWARD_EXEMPT_NIL_NON_GST", "INTEREST_LATE_FEE", "CASH_LEDGER_OFFSET", "CREDIT_LEDGER_OFFSET", "TAX_DEPOSITS"] as const;
type Row = Record<string, unknown>;
type Lane = GstGstr3bLaneSpec & { laneId: string };
type SourceBuild = { root: JsonObject; sourceModelHash: string; pack: Row; packHash: string; bindings: JsonObject; blockers: string[]; gstin: string; registrationId: string; periodFrom: string; periodTo: string };

function text(value: unknown, field: string, max = 256): string { if (typeof value !== "string" || value.trim() === "" || value.length > max) throw new DomainError("INVALID_GSTR3B_INPUT", `${field} must be a bounded nonblank string`); return value.trim(); }
function date(value: unknown, field: string): string { const result = text(value, field, 10); if (!/^\d{4}-\d{2}-\d{2}$/.test(result) || Number.isNaN(Date.parse(`${result}T00:00:00.000Z`)) || new Date(`${result}T00:00:00.000Z`).toISOString().slice(0, 10) !== result) throw new DomainError("INVALID_GSTR3B_DATE", `${field} must be a valid ISO date`); return result; }
function sha(value: unknown, field: string): string { const result = text(value, field, 64).toLowerCase(); if (!HASH.test(result)) throw new DomainError("INVALID_GSTR3B_HASH", `${field} must be lowercase SHA-256`); return result; }
function actor(kind: string): void { if (kind !== "AGENT" && kind !== "HUMAN") throw new DomainError("GSTR3B_ACTOR_INVALID", "GSTR-3B operations require an AGENT or HUMAN actor"); }
function parse(value: unknown, field: string): unknown { try { return JSON.parse(String(value)); } catch { throw new DomainError("GSTR3B_UPSTREAM_INTEGRITY", `${field} contains malformed JSON`); } }
function hashBytes(value: string): string { return createHash("sha256").update(Buffer.from(value, "utf8")).digest("hex"); }
function maskGstin(value: string): string { return `${value.slice(0, 2)}*********${value.slice(-4)}`; }
function maskJson(value: unknown, gstin: string): unknown { if (Array.isArray(value)) return value.map((item) => maskJson(item, gstin)); if (value && typeof value === "object") return Object.fromEntries(Object.entries(value as Row).map(([key, item]) => [key, key.toLowerCase() === "gstin" && item === gstin ? maskGstin(gstin) : maskJson(item, gstin)])); return value; }
function minor(value: unknown, field: string, allowNegative = false): string { const result = typeof value === "number" && Number.isSafeInteger(value) ? String(value) : String(value); const pattern = allowNegative ? /^-?(?:0|[1-9][0-9]*)$/ : /^(?:0|[1-9][0-9]*)$/; if (!pattern.test(result)) throw new DomainError("GSTR3B_FACT_MINOR_INVALID", `${field} must be an exact integer minor amount`); return result; }
function normalizeValues(value: unknown, key = "facts"): unknown { if (Array.isArray(value)) return value.map((item) => normalizeValues(item, key)); if (value && typeof value === "object") return Object.fromEntries(Object.entries(value as Row).sort(([a], [b]) => a.localeCompare(b)).map(([name, item]) => [name, /minor$|amount/i.test(name) ? minor(item, `${key}.${name}`) : normalizeValues(item, `${key}.${name}`)])); return value; }
function obj(value: unknown, field: string): Row { if (!value || typeof value !== "object" || Array.isArray(value)) throw new DomainError("INVALID_GSTR3B_FACT", `${field} must be an object`); return value as Row; }
function refs(value: unknown): AuthorityArtifactReference[] { if (!Array.isArray(value) || value.length < 2 || value.length > 4) throw new DomainError("GSTR3B_SCHEMA_ARTIFACTS_REQUIRED", "two to four official artifact references are required"); const rows = value.map((item, index) => { const row = obj(item, `artifactReferences[${index}]`); const kind = text(row.kind, `artifactReferences[${index}].kind`); if (!["LAW", "RULES", "SCHEMA", "INSTRUCTION"].includes(kind)) throw new DomainError("GSTR3B_SCHEMA_ARTIFACT_INVALID", "artifact kind is unsupported"); const sourceUrl = text(row.sourceUrl, `artifactReferences[${index}].sourceUrl`, 2048); if (!/^https:\/\//i.test(sourceUrl)) throw new DomainError("GSTR3B_SCHEMA_ARTIFACT_INVALID", "artifact sourceUrl must be HTTPS"); return { kind: kind as AuthorityArtifactReference["kind"], sourceUrl, sourceTitle: text(row.sourceTitle, `artifactReferences[${index}].sourceTitle`, 512), officialReleaseIdentifier: text(row.officialReleaseIdentifier, `artifactReferences[${index}].officialReleaseIdentifier`), officialReleaseDate: text(row.officialReleaseDate, `artifactReferences[${index}].officialReleaseDate`, 64), sha256: sha(row.sha256, `artifactReferences[${index}].sha256`) }; }); if (new Set(rows.map((r) => r.kind)).size !== rows.length || !rows.some((r) => r.kind === "SCHEMA") || !rows.some((r) => r.kind === "INSTRUCTION")) throw new DomainError("GSTR3B_SCHEMA_ARTIFACTS_REQUIRED", "SCHEMA and INSTRUCTION references are required and kinds must be unique"); return rows.sort((a, b) => a.kind.localeCompare(b.kind)); }
function laneSpec(value: unknown): Lane[] { if (!Array.isArray(value) || value.length < DEFAULT_LANES.length || value.length > 64) throw new DomainError("GSTR3B_LANE_SPEC_INVALID", "laneSpec must declare the bounded GSTR-3B lane inventory"); const rows = value.map((item, index) => { const row = obj(item, `laneSpec[${index}]`); return { laneId: text(row.laneId, `laneSpec[${index}].laneId`, 128), version: text(row.version, `laneSpec[${index}].version`, 64), label: text(row.label, `laneSpec[${index}].label`, 256), officialField: text(row.officialField, `laneSpec[${index}].officialField`, 256), ...(row.toleranceMinor === undefined ? {} : { toleranceMinor: minor(row.toleranceMinor, `laneSpec[${index}].toleranceMinor`) }) }; }); const ids = new Set(rows.map((r) => r.laneId)); if (ids.size !== rows.length || DEFAULT_LANES.some((id) => !ids.has(id))) throw new DomainError("GSTR3B_LANE_SPEC_INCOMPLETE", "laneSpec must include every stable GSTR-3B V1 lane"); return rows.sort((a, b) => a.laneId.localeCompare(b.laneId)); }
function packPayload(value: GstGstr3bSchemaPackRegisterPayload): { value: Row; hash: string } { const normalized = { schemaVersion: 1, jurisdiction: "IN", returnType: "GSTR3B", filingFrequency: value.filingFrequency, applicableFrom: date(value.applicableFrom, "applicableFrom"), ...(value.applicableTo ? { applicableTo: date(value.applicableTo, "applicableTo") } : {}), readinessContractVersion: text(value.readinessContractVersion, "readinessContractVersion", 128), ruleSnapshotReference: text(value.ruleSnapshotReference, "ruleSnapshotReference", 512), artifactReferences: refs(value.artifactReferences), packVersion: text(value.packVersion, "packVersion", 64), laneSpec: laneSpec(value.laneSpec), validationSchema: validateSchema(value.validationSchema), mappingSpec: validateMapping(value.mappingSpec, ["gstr3b"]), ...(value.supersedesPackId ? { supersedesPackId: text(value.supersedesPackId, "supersedesPackId") } : {}) }; if (!["MONTHLY", "QUARTERLY"].includes(String(value.filingFrequency)) || (normalized.applicableTo && normalized.applicableFrom > normalized.applicableTo)) throw new DomainError("GSTR3B_SCHEMA_IDENTITY_INVALID", "filing frequency or applicable dates are invalid"); return { value: normalized, hash: hashCanonical(normalized) }; }
function binding(value: unknown): GstGstr3bArtifactBindingPayload { const row = obj(value, "binding"); return { bookSetId: text(row.bookSetId, "bookSetId"), gstin: text(row.gstin, "gstin", 15), taxPeriodFrom: date(row.taxPeriodFrom, "taxPeriodFrom"), taxPeriodTo: date(row.taxPeriodTo, "taxPeriodTo"), schemaPackId: text(row.schemaPackId, "schemaPackId"), ...(row.gstr1ArtifactId ? { gstr1ArtifactId: text(row.gstr1ArtifactId, "gstr1ArtifactId") } : {}), ...(row.gstr1ArtifactHash ? { gstr1ArtifactHash: sha(row.gstr1ArtifactHash, "gstr1ArtifactHash") } : {}), ...(row.readinessSnapshotId ? { readinessSnapshotId: text(row.readinessSnapshotId, "readinessSnapshotId") } : {}) }; }
function factPayload(value: unknown): GstGstr3bFactPayload { const row = obj(value, "fact"); const factType = text(row.factType, "factType") as GstGstr3bFactType; if (!FACT_TYPES.includes(factType)) throw new DomainError("GSTR3B_FACT_TYPE_INVALID", "factType is unsupported"); const facts = normalizeValues(obj(row.facts, "facts")) as Row; const provenance = obj(row.provenance, "provenance"); if (!Object.keys(provenance).length) throw new DomainError("GSTR3B_PROVENANCE_REQUIRED", "provenance is required"); return { ...(row.factId ? { factId: text(row.factId, "factId") } : {}), gstin: text(row.gstin, "gstin", 15), taxPeriodFrom: date(row.taxPeriodFrom, "taxPeriodFrom"), taxPeriodTo: date(row.taxPeriodTo, "taxPeriodTo"), factType, facts, provenance }; }
function decision(value: unknown): { bookSetId: string; factId: string; expectedFactHash: string; reason: string } { const row = obj(value, "fact decision"); return { bookSetId: text(row.bookSetId, "bookSetId"), factId: text(row.factId, "factId"), expectedFactHash: sha(row.expectedFactHash, "expectedFactHash"), reason: text(row.reason, "reason") }; }
async function replay<T>(session: BusinessSession, tenantId: string, requestId: string, requestHash: string): Promise<CommandResult<T> | undefined> { const row = await session.querySingle("SELECT request_hash, result_json, result_hash FROM idempotency_records WHERE tenant_id = ? AND request_id = ?", [tenantId, requestId]); if (!row) return undefined; if (String(row.request_hash) !== requestHash) throw new IdempotencyConflictError("same request_id with different request hash"); if (computeResultHash(String(row.result_json)) !== String(row.result_hash)) throw new IdempotencyCorruptError("stored result_json hash mismatch"); return { resultJson: String(row.result_json), resultHash: String(row.result_hash), replayed: true } as CommandResult<T>; }
async function finish<T>(session: BusinessSession, envelope: CommandEnvelope<unknown> & { bookSetId?: string }, command: string, requestHash: string, value: T, entityType: string, entityId: string): Promise<CommandResult<T>> { const resultJson = canonicalJson(value); const resultHash = computeResultHash(resultJson); const now = new Date().toISOString(); await session.execute("INSERT INTO audit_records (id, tenant_id, book_set_id, command, action, actor_type, actor_id, source, reason, request_id, canonical_after_hash, change_summary, committed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId ?? null, command, command, envelope.actor.kind, envelope.actor.id, envelope.source, envelope.reason, envelope.requestId, resultHash, JSON.stringify({ entityType, entityId }), now, now]); await session.execute("INSERT INTO idempotency_records (id, tenant_id, request_id, request_hash, result_json, result_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.requestId, requestHash, resultJson, resultHash, now]); return { resultJson, resultHash }; }
async function packRow(session: BusinessSession, id: string): Promise<Row> { const row = await session.querySingle("SELECT * FROM gst_gstr3b_schema_packs WHERE id = ?", [id]); if (!row) throw new DomainError("GSTR3B_SCHEMA_PACK_NOT_FOUND", "GSTR-3B schema pack was not found"); return row; }
async function lifecycle(session: BusinessSession, id: string): Promise<string> { const row = await session.querySingle("SELECT event_type FROM gst_gstr3b_schema_pack_events WHERE pack_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", [id]); return String(row?.event_type ?? "PROPOSED"); }
function packView(row: Row, state: string): JsonObject { return { packId: String(row.id), jurisdiction: String(row.jurisdiction), returnType: String(row.return_type), filingFrequency: String(row.filing_frequency), applicableFrom: String(row.applicable_from), applicableTo: row.applicable_to == null ? undefined : String(row.applicable_to), readinessContractVersion: String(row.readiness_contract_version), ruleSnapshotReference: String(row.rule_snapshot_reference), packVersion: String(row.pack_version), canonicalHash: String(row.canonical_hash), lifecycle: state, supersedesPackId: row.supersedes_pack_id == null ? undefined : String(row.supersedes_pack_id), artifactReferences: parse(row.artifact_references_json, "artifact references"), laneSpec: parse(row.lane_spec_json, "lane spec"), validationSchema: parse(row.validation_schema_json, "validation schema"), mappingSpec: parse(row.mapping_spec_json, "mapping spec") }; }
function factView(row: Row, state: string): JsonObject { return { factId: String(row.id), tenantId: String(row.tenant_id), bookSetId: String(row.book_set_id), gstin: maskGstin(String(row.gstin)), taxPeriodFrom: String(row.tax_period_from), taxPeriodTo: String(row.tax_period_to), factType: String(row.fact_type), canonicalHash: String(row.canonical_hash), lifecycle: state, facts: maskJson(parse(row.facts_json, "facts"), String(row.gstin)), provenance: parse(row.provenance_json, "provenance") }; }
async function factLifecycle(session: BusinessSession, tenantId: string, bookSetId: string, id: string): Promise<string> { const row = await session.querySingle("SELECT event_type FROM gst_gstr3b_fact_events WHERE fact_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", [id, tenantId, bookSetId]); return String(row?.event_type ?? "PROPOSED"); }

export async function registerGstGstr3bSchemaPack(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bSchemaPackRegisterPayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); actor(envelope.actor.kind); const normalized = packPayload(envelope.payload); const requestHash = computeCommandHash(REGISTER, envelope, normalized.value); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const existing = await session.querySingle("SELECT * FROM gst_gstr3b_schema_packs WHERE canonical_hash = ?", [normalized.hash]); if (existing) return finish(session, envelope, REGISTER, requestHash, { ...packView(existing, await lifecycle(session, String(existing.id))), duplicate: true }, "GstGstr3bSchemaPack", String(existing.id)); if (normalized.value.supersedesPackId && !(await session.querySingle("SELECT id FROM gst_gstr3b_schema_packs WHERE id = ?", [normalized.value.supersedesPackId]))) throw new DomainError("GSTR3B_SCHEMA_SUPERSESSION_NOT_FOUND", "superseded GSTR-3B schema pack was not found"); const id = normalized.value.packId ? text(normalized.value.packId, "packId") : randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO gst_gstr3b_schema_packs (id,jurisdiction,return_type,filing_frequency,applicable_from,applicable_to,readiness_contract_version,rule_snapshot_reference,artifact_references_json,pack_version,lane_spec_json,validation_schema_json,mapping_spec_json,canonical_hash,supersedes_pack_id,created_at,created_by_actor_kind,created_by_actor_id) VALUES (?, 'IN', 'GSTR3B', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, normalized.value.filingFrequency, normalized.value.applicableFrom, normalized.value.applicableTo ?? null, normalized.value.readinessContractVersion, normalized.value.ruleSnapshotReference, canonicalJson(normalized.value.artifactReferences), normalized.value.packVersion, canonicalJson(normalized.value.laneSpec), canonicalJson(normalized.value.validationSchema), canonicalJson(normalized.value.mappingSpec), normalized.hash, normalized.value.supersedesPackId ?? null, now, envelope.actor.kind, envelope.actor.id]); await session.execute("INSERT INTO gst_gstr3b_schema_pack_events (id,pack_id,event_type,actor_kind,actor_id,reason,expected_pack_hash,request_id,request_hash,created_at) VALUES (?,?, 'REGISTERED',?,?,?,?,?,?,?)", [randomUUID(), id, envelope.actor.kind, envelope.actor.id, envelope.reason, normalized.hash, envelope.requestId, requestHash, now]); if (normalized.value.supersedesPackId) { const old = await session.querySingle("SELECT canonical_hash FROM gst_gstr3b_schema_packs WHERE id = ?", [normalized.value.supersedesPackId]); await session.execute("INSERT INTO gst_gstr3b_schema_pack_events (id,pack_id,event_type,actor_kind,actor_id,reason,expected_pack_hash,request_id,request_hash,created_at) VALUES (?,?, 'SUPERSEDED',?,?,?,?,?,?,?)", [randomUUID(), normalized.value.supersedesPackId, envelope.actor.kind, envelope.actor.id, envelope.reason, String(old?.canonical_hash), `${envelope.requestId}:supersede`, requestHash, now]); } return finish(session, envelope, REGISTER, requestHash, { ...packView(await packRow(session, id), "REGISTERED"), duplicate: false }, "GstGstr3bSchemaPack", id); }); }
async function decidePack(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bSchemaPackDecisionPayload>, eventType: "HUMAN_VERIFIED" | "REJECTED"): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); if (envelope.actor.kind !== "HUMAN") throw new DomainError("GSTR3B_SCHEMA_HUMAN_REQUIRED", "GSTR-3B schema pack decisions require a HUMAN actor"); const p = { packId: text(envelope.payload?.packId, "packId"), expectedPackHash: sha(envelope.payload?.expectedPackHash, "expectedPackHash"), reason: text(envelope.payload?.reason, "reason") }; const command = eventType === "HUMAN_VERIFIED" ? VERIFY : REJECT; const requestHash = computeCommandHash(command, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await packRow(session, p.packId); if (String(row.canonical_hash) !== p.expectedPackHash) throw new DomainError("GSTR3B_SCHEMA_PACK_CAS_MISMATCH", "expected GSTR-3B schema pack hash does not match"); if (await lifecycle(session, p.packId) !== "REGISTERED") throw new DomainError("GSTR3B_SCHEMA_PACK_LIFECYCLE_CONFLICT", "only a registered GSTR-3B pack can be decided"); const now = new Date().toISOString(); await session.execute("INSERT INTO gst_gstr3b_schema_pack_events (id,pack_id,event_type,actor_kind,actor_id,reason,expected_pack_hash,request_id,request_hash,created_at) VALUES (?,?,?,'HUMAN',?,?,?,?,?,?)", [randomUUID(), p.packId, eventType, envelope.actor.id, p.reason, p.expectedPackHash, envelope.requestId, requestHash, now]); return finish(session, envelope, command, requestHash, { ...packView(row, eventType), eventType }, "GstGstr3bSchemaPackEvent", p.packId); }); }
export const verifyGstGstr3bSchemaPack = (runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bSchemaPackDecisionPayload>) => decidePack(runner, envelope, "HUMAN_VERIFIED");
export const rejectGstGstr3bSchemaPack = (runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bSchemaPackDecisionPayload>) => decidePack(runner, envelope, "REJECTED");
export async function showGstGstr3bSchemaPack(runner: BusinessSessionRunner, packId: string): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const row = await packRow(session, text(packId, "packId")); return packView(row, await lifecycle(session, packId)); }); }

export async function proposeGstGstr3bFact(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bFactPayload> & { bookSetId: string }): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); actor(envelope.actor.kind); const p = factPayload(envelope.payload); const canonical = { schemaVersion: 1, gstin: p.gstin, taxPeriodFrom: p.taxPeriodFrom, taxPeriodTo: p.taxPeriodTo, factType: p.factType, facts: p.facts, provenance: p.provenance }; const requestHash = computeCommandHash(FACT_PROPOSE, envelope, canonical); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const registration = await session.querySingle("SELECT id FROM gst_registrations WHERE tenant_id = ? AND gstin = ? AND status = 'ACTIVE'", [envelope.tenantId, p.gstin]); if (!registration) throw new DomainError("GSTR3B_REGISTRATION_NOT_FOUND", "fact GSTIN is not an active tenant registration"); const existing = await session.querySingle("SELECT * FROM gst_gstr3b_facts WHERE tenant_id = ? AND book_set_id = ? AND gstin = ? AND tax_period_from = ? AND tax_period_to = ? AND canonical_hash = ?", [envelope.tenantId, envelope.bookSetId, p.gstin, p.taxPeriodFrom, p.taxPeriodTo, hashCanonical(canonical)]); if (existing) return finish(session, envelope, FACT_PROPOSE, requestHash, { ...factView(existing, await factLifecycle(session, envelope.tenantId, envelope.bookSetId, String(existing.id))), duplicate: true }, "GstGstr3bFact", String(existing.id)); const id = p.factId ?? randomUUID(); const now = new Date().toISOString(); const factHash = hashCanonical(canonical); await session.execute("INSERT INTO gst_gstr3b_facts (id,tenant_id,book_set_id,gstin,tax_period_from,tax_period_to,fact_type,facts_json,provenance_json,canonical_hash,created_at,created_by_actor_kind,created_by_actor_id,request_id,request_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", [id, envelope.tenantId, envelope.bookSetId, p.gstin, p.taxPeriodFrom, p.taxPeriodTo, p.factType, canonicalJson(p.facts), canonicalJson(p.provenance), factHash, now, envelope.actor.kind, envelope.actor.id, envelope.requestId, requestHash]); await session.execute("INSERT INTO gst_gstr3b_fact_events (id,fact_id,tenant_id,book_set_id,event_type,actor_kind,actor_id,reason,expected_fact_hash,request_id,request_hash,created_at) VALUES (?,?,?,?,'PROPOSED',?,?,?,?,?,?,?)", [randomUUID(), id, envelope.tenantId, envelope.bookSetId, envelope.actor.kind, envelope.actor.id, envelope.reason, factHash, `${envelope.requestId}:event`, requestHash, now]); return finish(session, envelope, FACT_PROPOSE, requestHash, { ...factView(await session.querySingle("SELECT * FROM gst_gstr3b_facts WHERE id = ?", [id]) as Row, "PROPOSED"), duplicate: false }, "GstGstr3bFact", id); }); }
async function decideFact(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bFactDecisionPayload>, eventType: "HUMAN_CONFIRMED" | "HUMAN_REJECTED"): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); if (envelope.actor.kind !== "HUMAN") throw new DomainError("GSTR3B_FACT_HUMAN_REQUIRED", "GSTR-3B fact decisions require a HUMAN actor"); const p = decision(envelope.payload); const command = eventType === "HUMAN_CONFIRMED" ? FACT_CONFIRM : FACT_REJECT; const requestHash = computeCommandHash(command, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await session.querySingle("SELECT * FROM gst_gstr3b_facts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.factId, envelope.tenantId, p.bookSetId]); if (!row) throw new DomainError("GSTR3B_FACT_NOT_FOUND", "GSTR-3B fact does not belong to tenant and BookSet"); if (String(row.canonical_hash) !== p.expectedFactHash) throw new DomainError("GSTR3B_FACT_CAS_MISMATCH", "expected GSTR-3B fact hash does not match"); if (await factLifecycle(session, envelope.tenantId, p.bookSetId, p.factId) !== "PROPOSED") throw new DomainError("GSTR3B_FACT_LIFECYCLE_CONFLICT", "only a proposed GSTR-3B fact can be decided"); const now = new Date().toISOString(); await session.execute("INSERT INTO gst_gstr3b_fact_events (id,fact_id,tenant_id,book_set_id,event_type,actor_kind,actor_id,reason,expected_fact_hash,request_id,request_hash,created_at) VALUES (?,?,?,?, '" + eventType + "', 'HUMAN',?,?,?,?,?,?)", [randomUUID(), p.factId, envelope.tenantId, p.bookSetId, envelope.actor.id, p.reason, p.expectedFactHash, envelope.requestId, requestHash, now]); return finish(session, { ...envelope, bookSetId: p.bookSetId }, command, requestHash, { ...factView(row, eventType), eventType }, "GstGstr3bFactEvent", p.factId); }); }
export const confirmGstGstr3bFact = (runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bFactDecisionPayload>) => decideFact(runner, envelope, "HUMAN_CONFIRMED");
export const rejectGstGstr3bFact = (runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bFactDecisionPayload>) => decideFact(runner, envelope, "HUMAN_REJECTED");
export async function listGstGstr3bFacts(runner: BusinessSessionRunner, tenantId: string, bookSetId: string): Promise<JsonObject[]> { return runner.withBusinessSession("read", async (session) => { const rows = await session.query("SELECT * FROM gst_gstr3b_facts WHERE tenant_id = ? AND book_set_id = ? ORDER BY tax_period_from, tax_period_to, fact_type, id", [tenantId, bookSetId]); return Promise.all(rows.rows.map(async (row) => factView(row, await factLifecycle(session, tenantId, bookSetId, String(row.id))))); }); }

function addAmount(target: Map<string, bigint>, key: string, value: unknown, field: string): void { target.set(key, (target.get(key) ?? 0n) + BigInt(minor(value, field))); }
function factDefaultLane(factType: string): string | undefined { const map: Record<string, string> = { PORTAL_GSTR1_LIABILITY: "OUTWARD_TAXABLE_SUPPLIES", PORTAL_GSTR2B_ITC: "ELIGIBLE_ITC", REVERSE_CHARGE_INWARD: "INWARD_REVERSE_CHARGE", IMPORT_GOODS_ITC: "ELIGIBLE_ITC", IMPORT_SERVICES_ITC: "ELIGIBLE_ITC", INELIGIBLE_ITC: "ITC_REVERSALS_INELIGIBLE", ITC_REVERSAL: "ITC_REVERSALS_INELIGIBLE", ITC_RECLAIM: "ELIGIBLE_ITC", INTEREST_LATE_FEE: "INTEREST_LATE_FEE", CASH_LEDGER: "CASH_LEDGER_OFFSET", CREDIT_LEDGER: "CREDIT_LEDGER_OFFSET", TAX_DEPOSIT: "TAX_DEPOSITS", NIL_EXEMPT_NONGST: "INWARD_EXEMPT_NIL_NON_GST", INTERSTATE_UNREGISTERED_SUMMARY: "INTERSTATE_UNREGISTERED_COMPOSITION_UIN", ECOMMERCE_9_5: "INTERSTATE_UNREGISTERED_COMPOSITION_UIN" }; return map[factType]; }
function factLanes(row: Row): Array<{ laneId: string; component: string; rateBps: string; amountMinor: string }> { const facts = parse(row.facts_json, "facts") as Row; const lanes = Array.isArray(facts.lanes) ? facts.lanes : facts.amountMinor !== undefined ? [{ laneId: factDefaultLane(String(row.fact_type)), component: facts.component ?? "TOTAL", rateBps: facts.rateBps ?? "0", amountMinor: facts.amountMinor }] : []; return lanes.map((item, index) => { const lane = obj(item, `facts.lanes[${index}]`); return { laneId: text(lane.laneId, `facts.lanes[${index}].laneId`, 128), component: text(lane.component ?? "TOTAL", `facts.lanes[${index}].component`, 16), rateBps: minor(lane.rateBps ?? 0, `facts.lanes[${index}].rateBps`), amountMinor: minor(lane.amountMinor, `facts.lanes[${index}].amountMinor`) }; }); }
async function sourceBuild(session: BusinessSession, tenantId: string, payload: GstGstr3bArtifactBindingPayload): Promise<SourceBuild> {
  const blockers: string[] = []; let pack: Row = {}; let packHash = "";
  try { pack = await packRow(session, payload.schemaPackId); packHash = String(pack.canonical_hash); if (payload.taxPeriodFrom < String(pack.applicable_from) || (pack.applicable_to != null && payload.taxPeriodTo > String(pack.applicable_to))) blockers.push("SCHEMA_PACK_NOT_APPLICABLE"); if (await lifecycle(session, payload.schemaPackId) !== "HUMAN_VERIFIED") blockers.push("SCHEMA_PACK_NOT_VERIFIED"); } catch (error) { if (error instanceof DomainError) blockers.push(error.code); else blockers.push("SCHEMA_PACK_UNAVAILABLE"); }
  const registration = await session.querySingle("SELECT id, gstin, status FROM gst_registrations WHERE tenant_id = ? AND gstin = ?", [tenantId, payload.gstin]); if (!registration || String(registration.status) !== "ACTIVE") blockers.push("GSTIN_NOT_ACTIVE");
  const factsRows = await session.query("SELECT * FROM gst_gstr3b_facts WHERE tenant_id = ? AND book_set_id = ? AND gstin = ? AND tax_period_from = ? AND tax_period_to = ? ORDER BY fact_type, id", [tenantId, payload.bookSetId, payload.gstin, payload.taxPeriodFrom, payload.taxPeriodTo]); const portal = new Map<string, bigint>(); const factIds: string[] = [];
  for (const row of factsRows.rows) { factIds.push(String(row.id)); if (await factLifecycle(session, tenantId, payload.bookSetId, String(row.id)) !== "HUMAN_CONFIRMED") { blockers.push(`FACT_NOT_CONFIRMED:${String(row.fact_type)}`); continue; } for (const lane of factLanes(row)) addAmount(portal, `${lane.laneId}|${lane.component}|${lane.rateBps}`, lane.amountMinor, "portal lane amount"); }
  const books = new Map<string, bigint>(); const bookTaxable = new Map<string, bigint>();
  const sales = await session.query("SELECT s.id, s.taxable_minor, s.tax_minor FROM gst_tax_snapshots s JOIN sales_invoices i ON i.id = s.sales_invoice_id AND i.tenant_id = s.tenant_id AND i.book_set_id = s.book_set_id WHERE s.tenant_id = ? AND s.book_set_id = ? AND s.document_type = 'SALE' AND i.status = 'POSTED' AND i.issue_date >= ? AND i.issue_date <= ?", [tenantId, payload.bookSetId, payload.taxPeriodFrom, payload.taxPeriodTo]);
  for (const row of sales.rows) { addAmount(bookTaxable, "OUTWARD_TAXABLE_SUPPLIES|TOTAL|0", row.taxable_minor, "book taxable"); const components = await session.query("SELECT component, rate_bps, taxable_minor, tax_minor FROM gst_tax_components WHERE tenant_id = ? AND book_set_id = ? AND snapshot_id = ? ORDER BY component, rate_bps", [tenantId, payload.bookSetId, row.id]); for (const component of components.rows) { addAmount(books, `OUTWARD_TAXABLE_SUPPLIES|${String(component.component)}|${minor(component.rate_bps, "book rate")}`, component.tax_minor, "book tax"); addAmount(bookTaxable, `OUTWARD_TAXABLE_SUPPLIES|${String(component.component)}|${minor(component.rate_bps, "book rate")}`, component.taxable_minor, "book taxable"); } }
  const purchases = await session.query("SELECT s.id, s.tax_minor, s.itc_treatment FROM gst_tax_snapshots s JOIN vendor_bills b ON b.id = s.vendor_bill_id AND b.tenant_id = s.tenant_id AND b.book_set_id = s.book_set_id WHERE s.tenant_id = ? AND s.book_set_id = ? AND s.document_type = 'PURCHASE' AND b.status = 'POSTED' AND b.bill_date >= ? AND b.bill_date <= ?", [tenantId, payload.bookSetId, payload.taxPeriodFrom, payload.taxPeriodTo]);
  for (const row of purchases.rows) { if (String(row.itc_treatment ?? "") === "PENDING_REVIEW" || row.itc_treatment == null) blockers.push("ITC_ELIGIBILITY_MISSING"); if (String(row.itc_treatment) !== "ELIGIBLE") continue; const components = await session.query("SELECT component, rate_bps, taxable_minor, tax_minor FROM gst_tax_components WHERE tenant_id = ? AND book_set_id = ? AND snapshot_id = ? ORDER BY component, rate_bps", [tenantId, payload.bookSetId, row.id]); for (const component of components.rows) addAmount(books, `ELIGIBLE_ITC|${String(component.component)}|${minor(component.rate_bps, "book rate")}`, component.tax_minor, "book ITC"); }
  for (const laneId of DEFAULT_LANES) if (!["OUTWARD_TAXABLE_SUPPLIES", "ELIGIBLE_ITC"].includes(laneId)) addAmount(books, `${laneId}|TOTAL|0`, 0, "empty book lane");
  const spec = Array.isArray(pack.lane_spec_json ? parse(pack.lane_spec_json, "lane spec") : undefined) ? parse(pack.lane_spec_json, "lane spec") as Lane[] : DEFAULT_LANES.map((laneId) => ({ laneId, version: "V1", label: laneId, officialField: "UNBOUND" })); const laneInventory = (spec as Lane[]).map((lane) => { const matching = [...portal.entries()].filter(([key]) => key.startsWith(`${lane.laneId}|`)); if (!matching.length) { blockers.push(`PORTAL_FACT_MISSING:${lane.laneId}`); return { ...lane, status: "BLOCKED_MISSING_DATA", portalMinor: "0", bookMinor: "0", varianceMinor: "0" }; } const portalAmount = matching.reduce((sum, [, amount]) => sum + amount, 0n); const bookAmount = [...books.entries()].filter(([key]) => key.startsWith(`${lane.laneId}|`)).reduce((sum, [, amount]) => sum + amount, 0n); const tolerance = lane.toleranceMinor ? BigInt(lane.toleranceMinor) : 0n; const variance = portalAmount - bookAmount; if (variance < -tolerance || variance > tolerance) blockers.push(`VARIANCE:${lane.laneId}`); return { ...lane, status: portalAmount === 0n && bookAmount === 0n ? "PRESENT_EMPTY" : "PRESENT_DATA", portalMinor: portalAmount.toString(), bookMinor: bookAmount.toString(), varianceMinor: variance.toString() }; });
  const gstr1 = payload.gstr1ArtifactId ? await session.querySingle("SELECT id, gstin, content_hash, tax_period_from, tax_period_to, readiness_snapshot_id FROM gst_gstr1_artifacts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [payload.gstr1ArtifactId, tenantId, payload.bookSetId]) : await session.querySingle("SELECT id, gstin, content_hash, tax_period_from, tax_period_to, readiness_snapshot_id FROM gst_gstr1_artifacts WHERE tenant_id = ? AND book_set_id = ? AND gstin = ? AND tax_period_from = ? AND tax_period_to = ? ORDER BY created_at DESC, id DESC LIMIT 1", [tenantId, payload.bookSetId, payload.gstin, payload.taxPeriodFrom, payload.taxPeriodTo]);
  if (gstr1) {
    if (String(gstr1.gstin) !== payload.gstin) blockers.push("GSTR1_GSTIN_MISMATCH");
    if (String(gstr1.tax_period_from) !== payload.taxPeriodFrom || String(gstr1.tax_period_to) !== payload.taxPeriodTo) blockers.push("GSTR1_PERIOD_MISMATCH");
    if (payload.gstr1ArtifactHash && String(gstr1.content_hash) !== payload.gstr1ArtifactHash) blockers.push("GSTR1_ARTIFACT_CAS_MISMATCH");
    if (payload.readinessSnapshotId && String(gstr1.readiness_snapshot_id) !== payload.readinessSnapshotId) blockers.push("GSTR1_READINESS_SNAPSHOT_MISMATCH");
    const readiness = await session.querySingle("SELECT v.readiness_status, s.payload_hash FROM gst_return_validations v JOIN gst_return_snapshots s ON s.id = v.snapshot_id AND s.tenant_id = v.tenant_id AND s.book_set_id = v.book_set_id WHERE v.snapshot_id = ? AND v.tenant_id = ? AND v.book_set_id = ? ORDER BY v.validated_at DESC, v.id DESC LIMIT 1", [String(gstr1.readiness_snapshot_id), tenantId, payload.bookSetId]);
    if (String(readiness?.readiness_status) !== "READY") blockers.push("GSTR1_READINESS_NOT_READY");
    if (!readiness?.payload_hash || !HASH.test(String(readiness.payload_hash))) blockers.push("GSTR1_READINESS_SNAPSHOT_INVALID");
    try {
      const snapshot = await session.querySingle("SELECT source_invoice_ids_json, frozen_source_hashes_json FROM gst_return_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [String(gstr1.readiness_snapshot_id), tenantId, payload.bookSetId]);
      const snapshotIds = snapshot ? parse(snapshot.source_invoice_ids_json, "GSTR-1 readiness source invoice IDs") : [];
      const frozen = snapshot ? parse(snapshot.frozen_source_hashes_json, "GSTR-1 readiness source hashes") : {};
      if (!Array.isArray(snapshotIds) || !snapshotIds.every((id) => typeof id === "string") || !frozen || typeof frozen !== "object" || Array.isArray(frozen)) throw new DomainError("GSTR3B_READINESS_SNAPSHOT_INVALID", "GSTR-1 readiness source bindings are malformed");
      const currentRows = await session.query("SELECT id, invoice_number, issue_date, total_minor FROM sales_invoices WHERE tenant_id = ? AND book_set_id = ? AND status = 'POSTED' AND issue_date >= ? AND issue_date <= ? ORDER BY id", [tenantId, payload.bookSetId, payload.taxPeriodFrom, payload.taxPeriodTo]);
      const currentIds = currentRows.rows.map((row) => String(row.id));
      const frozenHashes = frozen as Row;
      const snapshotStale = snapshotIds.length !== currentIds.length || snapshotIds.some((id) => !currentIds.includes(id)) || currentRows.rows.some((row) => hashBytes(JSON.stringify({ id: String(row.id), number: String(row.invoice_number), date: String(row.issue_date), total: Number(row.total_minor) })) !== String(frozenHashes[String(row.id)]));
      if (snapshotStale) blockers.push("GSTR1_READINESS_STALE");
    } catch (error) {
      if (error instanceof DomainError) blockers.push(error.code);
      else blockers.push("GSTR1_READINESS_SNAPSHOT_INVALID");
    }
  } else blockers.push("GSTR1_ARTIFACT_REQUIRED");
  const model = { schemaVersion: 1, jurisdiction: "IN", returnType: "GSTR3B", gstin: payload.gstin, taxPeriod: { from: payload.taxPeriodFrom, to: payload.taxPeriodTo }, registrationId: String(registration?.id ?? ""), gstr1Artifact: gstr1 ? { artifactId: String(gstr1.id), contentHash: String(gstr1.content_hash) } : undefined, factIds, laneInventory, books: { taxableByLane: Object.fromEntries([...bookTaxable.entries()].sort()), taxByLane: Object.fromEntries([...books.entries()].sort()) }, blockers: [...new Set(blockers)].sort() }; const sourceModelHash = hashCanonical(model); const bindings = { tenantId, bookSetId: payload.bookSetId, gstin: payload.gstin, registrationId: String(registration?.id ?? ""), taxPeriodFrom: payload.taxPeriodFrom, taxPeriodTo: payload.taxPeriodTo, schemaPackId: payload.schemaPackId, schemaPackHash: packHash, sourceModelHash, gstr1ArtifactId: gstr1 ? String(gstr1.id) : undefined, gstr1ArtifactHash: gstr1 ? String(gstr1.content_hash) : undefined, factIds }; const root = { gstr3b: model } as JsonObject; return { root, sourceModelHash, pack, packHash, bindings, blockers: [...new Set(blockers)].sort(), gstin: payload.gstin, registrationId: String(registration?.id ?? ""), periodFrom: payload.taxPeriodFrom, periodTo: payload.taxPeriodTo }; }
async function artifactRow(session: BusinessSession, tenantId: string, bookSetId: string, id: string): Promise<Row> { const row = await session.querySingle("SELECT * FROM gst_gstr3b_artifacts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, tenantId, bookSetId]); if (!row) throw new DomainError("GSTR3B_ARTIFACT_NOT_FOUND", "GSTR-3B artifact does not belong to tenant and BookSet"); return row; }
async function current(session: BusinessSession, row: Row): Promise<{ status: string; reasons: string[] }> { const bindings = parse(row.bindings_json, "artifact bindings") as GstGstr3bArtifactBindingPayload & { sourceModelHash?: string; schemaPackHash?: string }; const source = await sourceBuild(session, String(row.tenant_id), bindings); if (source.blockers.length) return { status: "BLOCKED", reasons: source.blockers }; if (source.sourceModelHash !== String(row.source_model_hash)) return { status: "STALE", reasons: ["SOURCE_FACTS_CHANGED"] }; if (source.packHash !== String(row.schema_pack_hash)) return { status: "STALE", reasons: ["SCHEMA_PACK_CHANGED"] }; if (source.gstin !== String(row.gstin)) return { status: "STALE", reasons: ["GSTIN_CHANGED"] }; if (hashBytes(String(row.content_json)) !== String(row.content_hash)) return { status: "BLOCKED", reasons: ["CONTENT_HASH_MISMATCH"] }; const validation = await session.querySingle("SELECT status FROM gst_gstr3b_validation_runs WHERE artifact_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", [row.id, row.tenant_id, row.book_set_id]); if (validation?.status === "LOCAL_INVALID") return { status: "LOCAL_INVALID", reasons: ["LATEST_LOCAL_VALIDATION_FAILED"] }; const exported = await session.querySingle("SELECT id FROM gst_gstr3b_export_activities WHERE artifact_id = ? AND tenant_id = ? AND book_set_id = ? LIMIT 1", [row.id, row.tenant_id, row.book_set_id]); return exported ? { status: "EXPORTED", reasons: [] } : validation?.status === "LOCAL_VALID" ? { status: "LOCAL_VALID", reasons: [] } : { status: "PREPARED", reasons: [] }; }
function artifactView(row: Row, state: string, reasons: string[] = []): JsonObject { const gstin = String(row.gstin); return { artifactId: String(row.id), tenantId: String(row.tenant_id), bookSetId: String(row.book_set_id), registrationId: String(row.registration_id), gstin: maskGstin(gstin), filingFrequency: String(row.filing_frequency), taxPeriodFrom: String(row.tax_period_from), taxPeriodTo: String(row.tax_period_to), schemaPackId: String(row.schema_pack_id), schemaPackHash: String(row.schema_pack_hash), sourceModelHash: String(row.source_model_hash), gstr1ArtifactId: row.gstr1_artifact_id == null ? undefined : String(row.gstr1_artifact_id), gstr1ArtifactHash: row.gstr1_artifact_hash == null ? undefined : String(row.gstr1_artifact_hash), contentByteLength: Number(row.content_byte_length), contentHash: String(row.content_hash), bindings: maskJson(parse(row.bindings_json, "artifact bindings"), gstin), status: state, statusReasons: reasons, createdAt: String(row.created_at), submitted: false, filed: false, accepted: false }; }
function mapped(source: SourceBuild): { content: unknown; contentJson: string; contentHash: string } { const result = evaluateMapping(parse(source.pack.mapping_spec_json, "mapping spec") as Mapping, source.root); const contentJson = `${canonicalJson(result)}\n`; return { content: result, contentJson, contentHash: hashBytes(contentJson) }; }

export async function previewGstGstr3b(runner: BusinessSessionRunner, tenantId: string, payload: GstGstr3bArtifactBindingPayload): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const source = await sourceBuild(session, tenantId, binding(payload)); let contentHash: string | undefined; try { contentHash = mapped(source).contentHash; } catch { source.blockers.push("MAPPING_EVALUATION_FAILED"); } return { schemaVersion: 1, status: "PREVIEW", gstin: maskGstin(payload.gstin), taxPeriodFrom: payload.taxPeriodFrom, taxPeriodTo: payload.taxPeriodTo, schemaPackHash: source.packHash || undefined, sourceModelHash: source.sourceModelHash, blockerCodes: [...new Set(source.blockers)].sort(), laneInventory: (source.root.gstr3b as Row).laneInventory, contentHash }; }); }
export async function prepareGstGstr3b(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bArtifactBindingPayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); actor(envelope.actor.kind); const payload = binding(envelope.payload); const requestHash = computeCommandHash(PREPARE, envelope, payload); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const source = await sourceBuild(session, envelope.tenantId, payload); if (source.blockers.length) throw new DomainError("GSTR3B_PREPARE_BLOCKED", "GSTR-3B preparation is blocked", { blockerCodes: source.blockers }); const result = mapped(source); if (Buffer.byteLength(result.contentJson, "utf8") > MAX_ARTIFACT_JSON) throw new DomainError("GSTR3B_ARTIFACT_TOO_LARGE", "GSTR-3B artifact exceeds the V1 size limit"); const existing = await session.querySingle("SELECT * FROM gst_gstr3b_artifacts WHERE tenant_id = ? AND book_set_id = ? AND gstin = ? AND tax_period_from = ? AND tax_period_to = ? AND content_hash = ?", [envelope.tenantId, payload.bookSetId, payload.gstin, payload.taxPeriodFrom, payload.taxPeriodTo, result.contentHash]); if (existing) return finish(session, envelope, PREPARE, requestHash, { ...artifactView(existing, "PREPARED"), duplicate: true }, "GstGstr3bArtifact", String(existing.id)); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO gst_gstr3b_artifacts (id,tenant_id,book_set_id,registration_id,gstin,filing_frequency,tax_period_from,tax_period_to,schema_pack_id,schema_pack_hash,source_model_hash,gstr1_artifact_id,gstr1_artifact_hash,content_json,content_byte_length,content_hash,bindings_json,created_at,created_by_actor_kind,created_by_actor_id,request_id,request_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", [id, envelope.tenantId, payload.bookSetId, source.registrationId, payload.gstin, String(source.pack.filing_frequency), payload.taxPeriodFrom, payload.taxPeriodTo, payload.schemaPackId, source.packHash, source.sourceModelHash, source.bindings.gstr1ArtifactId ?? null, source.bindings.gstr1ArtifactHash ?? null, result.contentJson, Buffer.byteLength(result.contentJson, "utf8"), result.contentHash, canonicalJson(source.bindings), now, envelope.actor.kind, envelope.actor.id, envelope.requestId, requestHash]); return finish(session, envelope, PREPARE, requestHash, { ...artifactView(await artifactRow(session, envelope.tenantId, payload.bookSetId, id), "PREPARED"), duplicate: false }, "GstGstr3bArtifact", id); }); }
export async function validateGstGstr3b(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bArtifactValidatePayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); actor(envelope.actor.kind); const p = envelope.payload; const expected = sha(p.expectedArtifactHash, "expectedArtifactHash"); const requestHash = computeCommandHash(VALIDATE, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await artifactRow(session, envelope.tenantId, p.bookSetId, p.artifactId); if (String(row.content_hash) !== expected) throw new DomainError("GSTR3B_ARTIFACT_CAS_MISMATCH", "expected artifact hash does not match"); const state = await current(session, row); if (["STALE", "BLOCKED"].includes(state.status)) throw new DomainError("GSTR3B_ARTIFACT_NOT_VALIDATABLE", "artifact is not bound to current upstream inputs", state); const pack = await packRow(session, String(row.schema_pack_id)); const diagnostics = validateValue(parse(pack.validation_schema_json, "validation schema") as Schema, parse(row.content_json, "artifact JSON")) as Diagnostic[]; const body = { schemaVersion: 1, artifactId: p.artifactId, artifactHash: expected, schemaPackId: String(pack.id), schemaPackHash: String(pack.canonical_hash), status: diagnostics.length ? "LOCAL_INVALID" : "LOCAL_VALID", diagnostics }; const validationHash = hashCanonical(body); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO gst_gstr3b_validation_runs (id,tenant_id,book_set_id,artifact_id,artifact_hash,schema_pack_hash,validation_hash,status,diagnostics_json,created_at,created_by_actor_kind,created_by_actor_id,request_id,request_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)", [id, envelope.tenantId, p.bookSetId, p.artifactId, expected, String(pack.canonical_hash), validationHash, body.status, canonicalJson(diagnostics), now, envelope.actor.kind, envelope.actor.id, envelope.requestId, requestHash]); return finish(session, { ...envelope, bookSetId: p.bookSetId }, VALIDATE, requestHash, { validationId: id, validationHash, ...body }, "GstGstr3bValidationRun", id); }); }
export async function exportGstGstr3b(runner: BusinessSessionRunner, envelope: CommandEnvelope<GstGstr3bArtifactExportPayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); if (envelope.actor.kind !== "HUMAN") throw new DomainError("GSTR3B_EXPORT_HUMAN_REQUIRED", "GSTR-3B export requires a HUMAN actor"); const p = envelope.payload; const expected = sha(p.expectedArtifactHash, "expectedArtifactHash"); const expectedValidation = sha(p.expectedValidationHash, "expectedValidationHash"); const requestHash = computeCommandHash(EXPORT, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await artifactRow(session, envelope.tenantId, p.bookSetId, p.artifactId); if (String(row.content_hash) !== expected) throw new DomainError("GSTR3B_ARTIFACT_CAS_MISMATCH", "expected artifact hash does not match"); const state = await current(session, row); if (["STALE", "BLOCKED", "LOCAL_INVALID"].includes(state.status)) throw new DomainError("GSTR3B_ARTIFACT_EXPORT_BLOCKED", "only a current LOCAL_VALID GSTR-3B artifact can be exported", state); const validation = await session.querySingle("SELECT status, validation_hash FROM gst_gstr3b_validation_runs WHERE artifact_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", [p.artifactId, envelope.tenantId, p.bookSetId]); if (!validation || String(validation.status) !== "LOCAL_VALID" || String(validation.validation_hash) !== expectedValidation) throw new DomainError("GSTR3B_VALIDATION_CAS_MISMATCH", "latest validation is not the exact requested LOCAL_VALID validation"); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO gst_gstr3b_export_activities (id,tenant_id,book_set_id,artifact_id,artifact_hash,validation_hash,actor_kind,actor_id,request_id,request_hash,created_at) VALUES (?,?,?,?,?,?, 'HUMAN',?,?,?,?,?)", [id, envelope.tenantId, p.bookSetId, p.artifactId, expected, expectedValidation, envelope.actor.id, envelope.requestId, requestHash, now]); return finish(session, { ...envelope, bookSetId: p.bookSetId }, EXPORT, requestHash, { exportActivityId: id, artifactId: p.artifactId, artifactHash: expected, validationHash: expectedValidation, status: "EXPORTED", filed: false, submitted: false, accepted: false }, "GstGstr3bExportActivity", id); }); }

export async function showGstGstr3b(runner: BusinessSessionRunner, tenantId: string, bookSetId: string, artifactId: string): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const row = await artifactRow(session, tenantId, bookSetId, artifactId); const state = await current(session, row); return artifactView(row, state.status, state.reasons); }); }
export async function statusGstGstr3b(runner: BusinessSessionRunner, tenantId: string, bookSetId: string, artifactId: string): Promise<JsonObject> { const view = await showGstGstr3b(runner, tenantId, bookSetId, artifactId); return { artifactId: view.artifactId, tenantId, bookSetId, status: view.status, statusReasons: view.statusReasons }; }
export async function contentGstGstr3b(runner: BusinessSessionRunner, tenantId: string, bookSetId: string, artifactId: string, revealSensitive = false, actorKind?: string): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const row = await artifactRow(session, tenantId, bookSetId, artifactId); const state = await current(session, row); const metadata = artifactView(row, state.status, state.reasons); if (!revealSensitive) return { ...metadata, revealed: false }; if (actorKind !== "HUMAN") throw new DomainError("GSTR3B_SENSITIVE_HUMAN_REQUIRED", "raw GSTR-3B content requires an explicit HUMAN actor"); return { ...metadata, revealed: true, content: parse(row.content_json, "artifact JSON") }; }); }
